/**
 * The procedural environment's gameplay data (docs/PROCEDURAL_ENVIRONMENT_AUDIT.md §9.1): species `env.<family>.<species>`
 * generated by tools/content/environment.mjs. Only what the simulation needs: sizes, collision shapes, surface,
 * navigation, concealment and placement rules. No Babylon, no files, no pictures (the client's own table,
 * client/src/content/environment.generated.ts, has those).
 *
 * Maps place species as ordinary props (`kind: 'prop'`, `model: 'env.…'`, optional `variant`), so MapMaker,
 * undo, settling, budgets and the hub keep working; `getProp` gives a PropDefinition view of a species with no
 * collision box: its collision comes from `environmentShapes` (map/environment.ts) instead.
 */
import { ENV_GENERATOR_VERSION, ENV_SPECIES } from './environment.generated.ts';
import type { SurfaceTypeId } from '../sim/surfaceTypes.ts';
import type { PropDefinition } from './props.ts';

/** MapMaker's Environment groups: Trees, Plants, Ground Cover, Rocks, Boulders, Cliffs. */
export const ENV_CATEGORIES = ['tree', 'plant', 'groundcover', 'rock', 'boulder', 'cliff'] as const;
export type EnvCategory = (typeof ENV_CATEGORIES)[number];

export type EnvVec3 = readonly [number, number, number];
/** Who a shape stops: everything (trunks, boulders, cliffs), or only shots and sight (a limb overhead). */
export type EnvBlocks = 'all' | 'shots';

/** A collision shape in the species' own space at scale 1 (game space: +Y up, +Z forward; metres). */
export type EnvShape =
  | { readonly kind: 'capsule'; readonly a: EnvVec3; readonly b: EnvVec3; readonly r: number; readonly blocks: EnvBlocks; readonly surface: SurfaceTypeId }
  | { readonly kind: 'box'; readonly min: EnvVec3; readonly max: EnvVec3; readonly yaw?: number; readonly blocks: EnvBlocks; readonly surface: SurfaceTypeId }
  | { readonly kind: 'hull'; readonly points: readonly EnvVec3[]; readonly blocks: EnvBlocks; readonly surface: SurfaceTypeId }
  | { readonly kind: 'mesh'; readonly positions: readonly number[]; readonly indices: readonly number[]; readonly blocks: EnvBlocks; readonly surface: SurfaceTypeId };

export interface EnvVariantData {
  /** Stored on placements (`PropEntity.variant`). Never reused. */
  readonly index: number;
  /** 'summer', 'autumn', 'snow', 'moss'…: material variants of one structure share its shapes. */
  readonly name: string;
  /** Generator seed (a structural variant has its own, and its own shapes). */
  readonly seed: number;
  /** Bounds [width x, height, depth z] at scale 1, as a footprint centred on the placement. */
  readonly size: EnvVec3;
  readonly shapes: readonly EnvShape[];
}

export interface EnvSpeciesData {
  readonly id: string;
  /** Bumped (with a note in its content file) whenever any shape or the size changes: a gameplay change. */
  readonly assetVersion: number;
  readonly family: string;
  readonly category: EnvCategory;
  readonly displayName: string;
  readonly nominalHeight: number;
  /** What its impacts look and sound like and, through the surface's ballistic class, what rounds do to it. */
  readonly surface: SurfaceTypeId;
  /** none: bots walk through it; obstacle: round it; boundary: a wall (cliffs). */
  readonly nav: 'none' | 'obstacle' | 'boundary';
  /** decorative: ground cover, may be grown and thinned by the renderer; cover and blocking: always drawn and always collide. */
  readonly role: 'decorative' | 'cover' | 'blocking';
  /** Hiding in it (sim/match.ts `hides`): a cylinder at scale 1, scaled with the placement; null = none. */
  readonly conceals: { readonly radius: number; readonly height: number } | null;
  readonly placement: { readonly maxSlopeDegrees: number; readonly minSpacing: number; readonly scale: readonly [number, number] };
  readonly variants: readonly EnvVariantData[];
}

export { ENV_GENERATOR_VERSION, ENV_SPECIES };

/** True for an environment species id (`env.<family>.<species>`). */
export const isEnvModel = (model: string): boolean => model.startsWith('env.');

let byId: Map<string, EnvSpeciesData> | undefined;
/** A species by id. */
export const getEnvSpecies = (id: string): EnvSpeciesData | undefined => (byId ??= new Map(ENV_SPECIES.map((s) => [s.id, s]))).get(id);

/** A placement's variant: the one it names, else the species' first (index 0). */
export function envVariant(species: EnvSpeciesData, index: number | undefined): EnvVariantData {
  return (index !== undefined && species.variants.find((v) => v.index === index)) || species.variants[0]!;
}

/** The surface a species is made of (env ids only). */
export const envSurfaceOf = (model: string): SurfaceTypeId | undefined => (isEnvModel(model) ? getEnvSpecies(model)?.surface : undefined);

/** The client file of a species' variant (public/env/<family>.<species>.<variant>.glb, tools/content/environment.mjs). */
export function envModelFile(model: string, variant?: number): string | undefined {
  const s = getEnvSpecies(model);
  if (!s) return undefined;
  return `env/${s.id.slice(4)}.${envVariant(s, variant).name}.glb`;
}

/** Legacy prop categories a species shows under where code still reads them (settling, palette search). */
const LEGACY_CATEGORY: Record<EnvCategory, string> = { tree: 'Trees', plant: 'Plants & Flowers', groundcover: 'Plants & Flowers', rock: 'Rocks & Wood', boulder: 'Rocks & Wood', cliff: 'Rocks & Wood' };

let views: Map<string, PropDefinition> | undefined;
/**
 * A PropDefinition view of a species (for `getProp`): size and file of its first variant, no collision box (its shapes
 * collide instead), conceals when it has a concealment cylinder.
 */
export function envPropDefinition(id: string): PropDefinition | undefined {
  views ??= new Map();
  const hit = views.get(id);
  if (hit) return hit;
  const s = getEnvSpecies(id);
  if (!s) return undefined;
  const v = s.variants[0]!;
  const def: PropDefinition = { id: s.id, file: envModelFile(s.id, v.index)!, displayName: s.displayName, category: LEGACY_CATEGORY[s.category], size: v.size, collision: null, ...(s.conceals ? { conceals: true } : {}) };
  views.set(id, def);
  return def;
}

/** Whether a placement of this species leans with the ground when drawn: plants only (anything that collides stands upright, as its collision does). */
export const envTilts = (model: string): boolean => {
  const c = getEnvSpecies(model)?.category;
  return c === 'plant' || c === 'groundcover';
};
